import { z } from "zod";

/** Paths are child indices relative to the imported scene, independent of UUIDs
 * regenerated by GLTFLoader. null explicitly disables an automatic mapping. */
export const rigMappingSchema = z
  .record(
    z.string().regex(/^[a-zA-Z][a-zA-Z0-9_]{0,63}$/),
    z.array(z.number().int().min(0)).max(128).nullable(),
  )
  .superRefine((mapping, context) => {
    const paths = new Set<string>(),
      roles = new Set<string>();
    for (const [role, path] of Object.entries(mapping)) {
      if (roles.has(role.toLowerCase()))
        context.addIssue({
          code: "custom",
          message: "Joint roles must be unique, ignoring case.",
        });
      roles.add(role.toLowerCase());
      if (path === null) continue;
      const key = path.join("/");
      if (paths.has(key))
        context.addIssue({
          code: "custom",
          message: "A bone cannot serve two joint roles.",
        });
      paths.add(key);
    }
    if (Object.keys(mapping).length > 256)
      context.addIssue({
        code: "custom",
        message: "Choose at most 256 joint mappings.",
      });
  });
export type RigMapping = z.infer<typeof rigMappingSchema>;
